{
  "passageId": "neoclassicism-romanticism-art",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "귀족의 향락을 주제로 삼았다는 사실이 로코코 미술을 부도덕하다고 판단하는 근거이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장식적인 기교에 치중했다는 사실이 로코코 미술을 경박하다고 평가하는 근거이다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "동일한 계몽주의적 기준에서 로코코 미술은 부정적으로, 고전주의 미술은 긍정적으로 평가된다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "고전주의가 계몽주의자들의 관심에 부합했다는 사실로 계몽주의가 고전주의의 재등장에 영향을 미쳤다는 설명을 뒷받침한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "사물에 내재하는 아름다움의 특질을 비례와 조화 및 질서라는 구체적인 내용으로 풀어 설명한다."
    },
    {
      "id": "R6",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "플라톤과 고전주의가 아름다움을 비례와 결부한다는 공통된 견해를 보인다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "아름다움이 객관적 형식에 내재한다는 관점이 기하학적 조형성을 갖춘 사물 자체가 즐거움을 준다는 설명의 근거가 된다."
    },
    {
      "id": "R8",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "빈켈만은 비례를 갖춘 사물에 객관적 아름다움이 존재한다는 고전주의의 관점을 이어받아 고대 그리스 미술을 전범으로 삼는다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "모방 대상으로 제시한 ‘고귀한 단순성’과 ‘고요한 위대함’이라는 용어의 뜻을 풀이한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "육체적 아름다움과 정신적 숭고함의 완벽한 일치가 절대미가 구현되었다는 평가를 뒷받침한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "고대 그리스 미술에 절대미가 구현되었다는 판단을 근거로 그것을 전범으로 삼아 모방해야 한다는 주장을 제시한다."
    },
    {
      "id": "R12",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "신고전주의 화가들이 빈켈만의 미학을 이론적 토대로 받아들이고 그 규범을 따른다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "고전주의 규범의 준수가 매끈한 표면과 뚜렷한 윤곽선 및 안정된 구도라는 구체적 특징으로 드러난다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "고전주의 규범을 준수한다는 내용을 색채보다 형태를 강조한다는 표현상의 특징으로 구체화한다."
    },
    {
      "id": "R15",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "계몽주의의 영향이 도덕적 시민 양성을 위한 미술을 지향하게 된 사상적 배경이다."
    },
    {
      "id": "R16",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "도덕적 시민 양성에 필요한 교훈을 전달하려는 목적을 위해 애국적 희생을 보여 주는 영웅 이야기를 선택한다."
    },
    {
      "id": "R17",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "정신적 숭고함과 도덕성을 드러내기 위한 수단으로 영웅의 표정을 침착하게 표현한다."
    },
    {
      "id": "R18",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "감정의 절제라는 ‘고요한 위대함’의 미학적 원리를 작품 속 영웅의 표정 표현에 적용한다."
    },
    {
      "id": "R19",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "신고전주의 화가들은 시민 사회에 걸맞은 미술을 추구한 계몽주의자들의 지향을 받아들여 도덕적 교훈을 표현한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 개체가 고유한 의미를 가진다는 헤르더의 관점이 고대 그리스 미술만을 보편적 이상으로 삼는 주장을 비판하는 근거이다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 개체의 가치가 동등하다는 판단을 근거로 고대 그리스 미술에 절대적 지위를 부여하는 견해를 문제 삼는다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "변화와 시간의 흐름을 중시하는 관점이 시대를 초월한 모방론을 시대착오적이라고 판단하는 근거이다."
    },
    {
      "id": "R23",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "헤르더가 고대 그리스 미술에 보편적 절대미를 인정한 빈켈만의 견해를 명시적으로 문제 삼는다."
    },
    {
      "id": "R24",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "헤르더가 고대 그리스 미술을 모방해야 한다는 빈켈만의 주장을 시대착오적이라고 반박한다."
    },
    {
      "id": "R25",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "헤르더의 상대주의적 비판이 신고전주의를 거부하고 개인의 표현을 중시하는 낭만주의의 출발 배경이다."
    },
    {
      "id": "R26",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "헤르더의 사상이 촉발한 개인의 각성과 자기표현 미술의 등장이 낭만주의의 개인 중심적 지향이 형성된 배경이다."
    },
    {
      "id": "R27",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "흄과 낭만주의는 아름다움의 근원을 사물 자체가 아니라 감상자의 마음과 감각적 즐거움에서 찾는다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사물 자체에 미추가 정해져 있지 않다는 관점이 기존에 배제되었던 감정과 존재로 미술의 주제가 확장되도록 한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자유로운 감정 표현이라는 낭만주의의 특징을 강렬한 채색과 거친 붓 자국 및 역동적인 구도라는 표현 방식으로 구체화한다."
    },
    {
      "id": "R30",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "아름다움의 근원에 대해 고전주의는 사물의 객관적 특질을, 낭만주의는 감상자의 주관적 즐거움을 제시한다."
    },
    {
      "id": "R31",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "표면 처리와 구도라는 동일한 기준에서 신고전주의의 매끈함과 안정성이 낭만주의의 거침과 역동성에 대비된다."
    },
    {
      "id": "R32",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "조형 요소의 강조점에서 신고전주의는 형태를, 낭만주의는 색채를 우선한다."
    },
    {
      "id": "R33",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "감정 표현에 대해 신고전주의는 도덕성을 위한 절제를, 낭만주의는 개인 감정의 자유로운 표출을 중시한다."
    },
    {
      "id": "R34",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "고대 그리스의 애국적 영웅 중심이던 미술의 주제가 낭만주의에서 불안과 공포 및 환상적 존재의 영역으로 넓어진다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "폭넓은 주제와 감정 중심의 다양한 표현 방식이 개별성과 다양성을 꽃피웠다는 종합적 평가를 뒷받침한다."
    },
    {
      "id": "R36",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "낭만주의가 신고전주의의 객관적 미와 엄격한 규범을 단순히 달리 보는 데 그치지 않고 거부하는 입장으로 제시된다."
    }
  ]
}

